from pathlib import Path
import json
P=Path(__file__).parent
D='2026-11-05'
def write(name,obj):
 (P/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
def source(n,title,authors,year,url,kind,locator,limit,lineage,access='full-text'):
 return dict(id=f'DIG-S{n:02}',title=title,authors=authors,year=year,url=url,source_type=kind,access=access,locator=locator,scope_limit=limit,accessed=D,evidence_lineage=lineage)
sources=[
source(1,'Information Management: A Proposal',['Tim Berners-Lee'],1989,'https://www.w3.org/History/1989/proposal.html','historical-primary','HTML transcription; Losing Information at CERN; A solution: Hypertext; CERN Requirements; Non requirements. Inspected these sections and the transcription notice.','A proposal and author recollection of Enquire, not measured global adoption. Written March 1989, recirculated May 1990, later HTML transcription; historical errors in incidental references are not endorsed.','Original CERN proposal by its author, preserved as a later W3C-hosted transcription. Direct evidence of proposed requirements; later framing supplied by author.'),
source(2,'Licensing the Web',['Tim Smith','François Flückiger'],'undated','https://home.cern/science/computing/the-birth-of-the-web/licensing-web/','institutional-synthesis','Public releases of Web software; Open Source release; The first CERN Open Source software licence; MIT Open Source release.','CERN participant retrospective quotes releases; original signed release not separately acquired. No causal estimate of licensing impact. Broad claims about free-software history and W3C dates are not used.','Retrospective CERN account by institutional participants, reproducing 1993–1995 legal/announcement text; not independent of the CERN institutional tradition or original Web developers.'),
source(3,'Computer and Internet Use in the United States: 2015 (ACS-37)',['Camille Ryan','Jamie M. Lewis','U.S. Census Bureau'],2017,'https://www.census.gov/content/dam/Census/library/publications/2017/acs/acs-37.pdf','official-statistics','pp. 1–3, Figure 1, CPS/ACS comparison box; Tables 1–2 and high-connectivity definition. Full PDF acquired; selected sections inspected.','Households, not persons or active-use minutes. CPS and ACS use different questions/methods. ACS broadband includes mobile and handheld includes more than smartphones.','Original Census analysis of CPS historical survey series and 2015 ACS. Figures from these two surveys are distinct series, not independent confirmations of identical levels.'),
source(4,'Communications Market Report 2015: Internet and online content',['Ofcom'],2015,'https://www.ofcom.org.uk/siteassets/resources/documents/research-and-data/cmr/cmr15/uk_5.pdf?v=322209','official-statistics','Section 5.2; printed pp. 341–347, Figures 5.14–5.20; reported importance question QE11/QE40 and base n=3095. Read through web PDF extraction.','Device take-up, household ownership and most-important-device questions have different bases. Report narrative uses inconsistent 2014 smartphone importance percentage; no 2014 percentage used here.','Ofcom Technology Tracker W1 2015, partly combined with commercial audience-measurement sources elsewhere in report. Claims here use the original Ofcom survey, not comScore.'),
source(5,'The Smartphone Difference / U.S. Smartphone Use in 2015',['Aaron Smith','Pew Research Center'],2015,'https://www.pewresearch.org/internet/wp-content/uploads/sites/9/2015/03/PI_Smartphones_0401151.pdf','scholarly-analysis','pp. 1–4, 14–19 and 20–22; smartphone-dependence definitions and survey methods. Full PDF acquired; relevant sections inspected.','Ownership national estimate from November 2014 omnibus polls; usage/financial circumstances from October 2014 American Trends Panel. Dependence has a narrower definition than later smartphone-only indicators. Self-report, not causal assignment.','Original Pew omnibus and American Trends Panel surveys with Knight Foundation support. National ownership and panel behavioural estimates are separate samples; repeated summaries within report are not independent evidence.'),
source(6,'Telecom Statistics India-2024',['Economic Research Unit, Department of Telecommunications, Government of India'],2024,'https://www.dot.gov.in/static/uploads/2025/07/f44e3a674c85aa98cd6fa881e4462b57.pdf','official-statistics','Table 1.10 p. 14 (PDF p.21); Table 6.2 p.61 (PDF p.68), including period footnote. Full PDF acquired; tables inspected.','Official compilation of TRAI provider returns. Subscription counts are not unique people; revenue per GB is not advertised tariff. Calendar-year data switch to financial years from 2020–21. Nominal rupees.','DoT compilation explicitly sources TRAI quarterly/yearly Performance Indicator Reports. Underlying provider administrative returns were not independently audited; DoT and TRAI are not two independent datasets.'),
source(7,'Annual Status of Education Report (Rural) 2021',['ASER Centre'],2021,'https://img.asercentre.org/docs/aser2021forweb.pdf','scholarly-analysis','Sample Design pp.15–16; Household Survey Major Findings pp.28–31, Tables 8–12 and 2018 comparison footnote. Full PDF acquired; sections inspected.','2021 telephone sample drawn from prior survey phone numbers; no-phone households excluded from 2018 comparison. Rural children ages 5–16, enrolled-child device tables. Availability is not personal ownership or educational effect.','Original ASER survey of 76,706 households, reaching 75,234 children, using a frame based on ASER 2018; 2018 comparisons reconstructed to exclude households without mobile phones. Not independent cross-sectional samples with identical coverage.'),
source(8,'Mobile Money: The Economics of M-PESA (NBER Working Paper 16721)',['William Jack','Tavneet Suri'],2011,'https://www.nber.org/system/files/working_papers/w16721/w16721.pdf','scholarly-analysis','Sections II–IV; PDF pp.6–11, 13–15, 26–27; printed pp.25–26 Tables 14a–14b. Full PDF acquired through direct retrieval after web tool returned 403 for a different NBER PDF path.','Working paper, not NBER peer review. Some aggregate comparisons and claims of fastest adoption are not used. Author collaboration with Safaricom/Vodafone and survey commissioning by FSD/CBK acknowledged. Survey experience and user composition are observational.','Original authors’ 2008/2009 household panel and agent research; some network data supplied by Safaricom. Shares baseline research and authors with DIG-S09, so not independent corroboration of welfare impacts.'),
source(9,'The long-run poverty and gender impacts of mobile money',['Tavneet Suri','William Jack'],2016,'https://www.findevgateway.org/sites/default/files/publications/files/new_jack_and_suri_paper_1.pdf','scholarly-analysis','Science 354(6317), pp.1288–1292, DOI 10.1126/science.aah5309; equations 1–2; Tables 1–3; attrition and mechanisms discussion. All five article pages inspected; supplement not acquired.','Publisher-form article hosted by FinDev Gateway; direct PDF succeeded despite web-tool 403. Identification relies on early agent rollout assumptions, fixed effects and controls; substantial attrition, Nairobi later excluded. Extrapolated national poverty total is not a count. Supplemental robustness tables not independently inspected.','Original five-wave 2008–2014 household panel, extending the data programme in DIG-S08; uses earlier research’s falsification and rollout tests. This analysis is not an independent replication of those earlier findings.'),
source(10,'2024 FinAccess Household Survey Main Report',['Central Bank of Kenya','Kenya National Bureau of Statistics','FSD Kenya'],2024,'https://www.centralbank.go.ke/wp-content/uploads/2024/12/2024-FINACCESS-HOUSEHOLD-SURVEY-MAIN-REPORT.pdf','official-statistics','Survey Design and Methodology pp.3–5 (PDF pp.15–17); Figure 2.3 p.12; usage section p.26. Full PDF acquired by direct retrieval after web timeout.','Interview target 16+, but substantive access/use analysis is adults 18+. Current-use responses cover all mobile-money providers, not M-PESA alone or active accounts within a stated monthly window. Institution has financial-inclusion policy interests.','New national household survey based on Kenya Household Master Sample Frame from 2019 census, separate from Suri/Jack panel. Institutional partnership with FSD and CBK overlaps earlier research commissioning but observations are a different survey.'),
source(11,'Online Nation 2024 Report',['Ofcom'],2024,'https://www.ofcom.org.uk/siteassets/resources/documents/research-and-data/online-research/online-nation/2024/online-nation-2024-report.pdf?v=386238','official-statistics','pp.66–69, especially p.68 and footnote 178; web PDF extraction inspected.','p.68 reports 4% VR gaming in 2023 followed by an inconsistent 3%:2023 parenthesis. Underlying DIG-S15 establishes the 4% level; no growth rate inferred. Nearby console/phone statistics use different trackers/years.','Secondary presentation of Ofcom Adults’ Media Literacy Tracker 2023, Technology Tracker 2024 and commercial Ampere sources. Its VR figure repeats DIG-S15; it is not independent corroboration.'),
source(12,'Quantifying the Effects of Working in VR for One Week',['Verena Biener','Snehanjali Kalamkar','Negar Nouri','Eyal Ofek','Michel Pahud','John J. Dudley','Jinghui Hu','Per Ola Kristensson','Maheshya Weerasinghe','Klen Čopič Pucihar','Matjaž Kljun','Stephan Streuber','Jens Grubert'],2022,'https://arxiv.org/pdf/2206.03189','experiment','Author version arXiv:2206.03189v2, 8 June 2022; sections 3.1–3.4, 3.6–3.7 and 4; PDF pp.1–5,8–9.','16 university employee/researcher completers plus two withdrawals; counterbalanced own-work study. Quest 2/remote-desktop/K830 setup deliberately matches conventional display; not an optimised spatial workspace. Subjective productivity is not objective output. Some authors affiliated with Microsoft Research.','Original controlled within-subjects study at three physical locations in Germany, with study dataset offered by authors. Later behavioural analyses of this study would not be independent samples.'),
source(13,'Meta Platforms, Inc. Form 10-K for year ended December 31, 2023',['Meta Platforms, Inc.'],2024,'https://www.sec.gov/Archives/edgar/data/1326801/000132680124000012/meta-20231231.htm','historical-primary','Part I Reality Labs Products and relevant risk discussion; Note 16 Segment and Geographical Information, printed pp.124–125; segment revenue/operating-loss table.','Commercial company disclosure. Audited segment finances do not identify headset users, retention or per-device subsidy. Segment includes AR, mixed reality and VR; allocations and research costs prevent treating loss as cost of observed VR consumption.','Company accounting and management disclosures filed with SEC; no separate original adoption dataset used here. SEC hosting is not an independent estimate of market adoption.'),
source(14,'Microsoft 2015 Annual Report',['Microsoft Corporation'],2015,'https://www.microsoft.com/investor/reports/ar15/index.html','historical-primary','Shareholder letter; Create more personal computing; MD&A Phone Hardware; Impairment, Integration, and Restructuring Expenses.','Commercial management narrative and accounting disclosure. FY2014 phone sales only post-Nokia acquisition; 2015 versus 2014 sales growth not comparable full years. Non-Lumia is not equivalent to Windows Phone. Impairment is neither user count nor causal attribution.','Company annual accounts, acquisition-related valuations and management strategy; no independent carrier, developer or consumer causal dataset. Narrative and figures originate in the same company.'),
source(15,'Adults’ Media Literacy Core Survey 2023 Data Tables',['Ofcom','Critical Research'],2024,'https://www.ofcom.org.uk/siteassets/resources/documents/research-and-data/data/statistics/2024/adults-media-literacy-tracker/adults-media-literacy-core-survey-2023-data-tables?v=330749','official-statistics','Table 70 M6A printed pp.292–294 (PDF pp.298–300); Table 74 G1 printed pp.307–308 (PDF pp.313–314); fieldwork 27 September–12 November 2023.','3,643 UK adults 16+, mixed quota interviews; G1 multi-code, no monthly/weekly recall threshold. M6A base is 3,351 unweighted smartphone users, weighted base 3,231; task difficulty is a perception. Percentages are rounded.','Original tabulations from Ofcom 2023 Core Survey. DIG-S11 repeats these gaming data; DIG-S16 documents this same sample, not another independent survey.'),
source(16,'Adults’ Media Literacy Research 2023 Technical Report',['Ofcom','Critical Research'],2024,'https://www.ofcom.org.uk/siteassets/resources/documents/research-and-data/data/statistics/2024/adults-media-literacy-tracker/adults-media-literacy-tracker-2023-technical-report?v=330751','official-statistics','pp.4–5 methodological/trend notes; pp.7–8 Core study sampling, interviewing and reporting.','Methodological documentation of a quota sample, not a separate adoption observation. Adults, not households, are the target for weighted reported proportions. 2021 trend comparisons are only indicative because methods changed.','Methods for the same original 2023 Core Survey tabulated in DIG-S15 and summarised in DIG-S11. Provides denominator/sampling provenance, not independent effect corroboration.')]
write('sources.json',sources)

def ref(s,loc,support): return dict(source_id=f'DIG-S{s:02}',locator=loc,supports=support)
def desc(reason): return {'status':'descriptive-only','reason':reason}
def test(status,chain,rival,obs,found,ambiguity,timing='pre-search candidate'):
 return dict(status=status,mechanism_chain=chain,strongest_rival=rival,discriminating_observation=obs,evidence_sought_found=found,remaining_ambiguity=ambiguity,hypothesis_timing=timing)
def claim(n,cs,statement,etype,conf,status,refs,counter,limits,t=None):
 return dict(id=f'DIG-K{n:02}',case_ids=[f'DIG-C{c:02}' for c in cs],statement=statement,evidence_type=etype,confidence=conf,causal_status=status,sources=refs,counterevidence=counter,inference_limits=limits,test=t or desc('The bounded statistic or documentary statement is reported without assigning the cause of diffusion.'))
claims=[
claim(1,[1],'The 1989 CERN proposal specified remote access, heterogeneous computers, decentralised linking and access to existing information; text on 24-by-80 screens was initially sufficient and elaborate security/accounting was not a primary local requirement.','historical-primary','high','descriptive',[ref(1,'CERN Requirements; Non requirements','Author’s explicit design priorities.')],'Later consumer uses could require very different interfaces and protection.','A proposal establishes intent, not successful deployment or the causes of mass diffusion.'),
claim(2,[1],'CERN released specified Web components to the public domain in April 1993 and later used permissive royalty-free licensing; this removed a reuse-permission barrier, but its contribution to later diffusion is not identified here.','institutional-synthesis','medium','mechanism-supported',[ref(2,'Public releases of Web software; Open Source release; The first CERN Open Source software licence','Dates and terms of releases, with retrospective rationale.')],'Working networks, usable interfaces and content could explain diffusion despite permissive licensing being present.','Original signed release not separately acquired; no matched diffusion counterfactual.',test('underdetermined','Reuse permission -> implementers can copy/modify code without licensing payment -> potentially lower entry cost -> wider deployment.','Network growth and browser/interface improvement could drive the same observed expansion.','Compare otherwise similar implementers facing different effective licensing barriers before/after release.','Read DIG-S01 design requirements and DIG-S02 release history; found legal change but no controlled uptake comparison.','Cannot rank licence change against technical or demand complements.')),
claim(3,[2],'The Census historical CPS series reports computers in about 8% of US households in 1984, 51% in 2000 and 79% in 2015; household internet use was 18% in 1997 and 73% in 2015.','official-statistics','high','descriptive',[ref(3,'p.2 Computer and Internet Use over Time; Figure 1 p.3','CPS series and cross-survey warning.')],'ACS gives different levels because questions, weighting and collection differ.','Rounded household estimates; no individual-use rate or causal speed comparison across technologies.'),
claim(4,[2],'In the 2015 ACS, 78% of US households had desktop/laptop access, 75% handheld-computer access and 77% broadband; 62% had all three, showing household-level coexistence.','official-statistics','high','descriptive',[ref(3,'p.2 Highlights; Tables 1–2; footnote 1','Device/subscription categories and joint high-connectivity indicator.')],'Household coexistence could include disused equipment or different people rather than task complementarity for one person.','Broadband includes mobile; handheld includes more than smartphones. This is access/ownership, not active usage.'),
claim(5,[3],'In early 2015, 33% of UK internet users aged 16+ named smartphones and 30% laptops as their most important internet-access device.','official-statistics','high','descriptive',[ref(4,'pp.346–347, Figure 5.20, QE11/QE40; n=3095','Question, denominator and levels.')],'Older respondents selected computers more often.','Self-reported importance is not ownership, share of tasks or minutes, and does not isolate pocketability.'),
claim(6,[3],'Ofcom reported tablet availability in 54% of UK households in 2015; among internet users aged 55+, laptops (36%), desktops (27%) and tablets (22%) were the leading most-important-device choices.','official-statistics','high','descriptive',[ref(4,'pp.341–344 Figures 5.14,5.17; pp.346–347 Figure 5.20','Household tablet measure and age-specific preferences.')],'Device choice differs by age, resources and tasks; broad smartphone growth did not imply no use of alternatives.','The household tablet denominator differs from the age-specific internet-user denominator; no common device price comparison.'),
claim(7,[3],'Pew’s November 2014 surveys found smartphone ownership among 64% of US adults, against 35% in 2011; 7% of adults had both no home broadband and few alternative ways to get online.','scholarly-analysis','high','descriptive',[ref(5,'pp.2–3; Smartphone dependence section pp.16–18','Ownership history and conjunctive definition.')],'A broader measure gives 19% experiencing at least one constraint, and should not be called the same dependent group.','Late-2014 observations published in 2015; adult measure, not households or every form of smartphone-only access.'),
claim(8,[3],'Among Pew’s narrowly defined smartphone-dependent users in its 2014 research, 48% reported having previously suspended service because of financial hardship.','scholarly-analysis','high','descriptive',[ref(5,'p.4 summary and p.19','Financial-suspension response and dependence definition.')],'Dependent users still used smartphones; this does not show they would prefer computers if unconstrained.','Past episode with no fixed recent window; observational self-report, not current disconnected share.'),
claim(9,[3],'In the 2023 Ofcom Core Survey, 68% of UK smartphone users aged 16+ agreed that completing forms and working on documents was harder on their phone than on a laptop or desktop.','official-statistics','high','descriptive',[ref(15,'Table 70 M6A, pp.292–294; unweighted base3351','Combined agreement percentage and question.'),ref(16,'pp.7–8','Adult weighting, sample and interview methods.')],'Difficulty can coexist with useful portable access; the table does not measure objective task time or ownership of alternatives.','Perceived task difficulty in a mixed quota sample. Cannot be used as a whole-market ergonomic ranking.'),
claim(10,[4],'India’s official compilation reports nominal average wireless-data revenue realisation falling from ₹268.97/GB in calendar2014 to ₹9.12/GB in FY2023–24, while monthly data revenue per data subscriber rose from ₹71.25 to ₹211.36.','official-statistics','high','descriptive',[ref(6,'Table 6.2 p.61 and period/source footnote','Both series and calendar/financial-year distinction.')],'Higher usage and changing customer composition can accompany lower per-unit revenue.','Not list prices, household bills or a causal effect of competition; no inflation or income adjustment.'),
claim(11,[4],'At March2024 the official Indian compilation recorded 111.75 urban and 44.16 rural internet subscriptions per100 inhabitants.','official-statistics','high','descriptive',[ref(6,'Table1.10 p.14','Urban/rural subscription-density observations.')],'Multiple subscriptions can make the ratio exceed100.','Not unique internet users, physical population coverage, connection quality or literacy.'),
claim(12,[4],'ASER’s rural enrolled-child comparison reports a smartphone at home for 36.5% in2018 and67.6% in2021; the2018 comparison excludes households without mobile phones to match telephone-survey coverage more closely.','scholarly-analysis','high','descriptive',[ref(7,'Sample Design pp.15–16; Tables8–11 pp.28–29 and footnotes','Levels and sample restriction.')],'Changed reachability and nonresponse can remain even after excluding no-phone households from2018.','Not all Indian children or personally owned phones; not a causal effect of school closures.'),
claim(13,[4],'Among ASER2021 enrolled children with a smartphone at home,26.1% had no access to it for studies and27.0% had access at all times.','scholarly-analysis','high','descriptive',[ref(7,'Table10 p.28; Table12 p.31','Conditional access shares.')],'A phone’s presence could still help some tasks or times; lack of study access does not uniquely identify why access was constrained.','Household device availability and child control are distinct outcomes; no measured learning effect.'),
claim(14,[5],'M-PESA’s early Kenyan configuration combined SMS-capable phones with a carrier network, registered users, cash/e-money agents and bank-held funds; smartphone internet was not a prerequisite for this implementation.','scholarly-analysis','high','mechanism-supported',[ref(8,'SectionII, PDFpp.6–11','Operational architecture, identification, agent liquidity and bank links.')],'Some services could operate through banks or physical transfers; agents were not the only conceivable transfer architecture.','Bounded to early M-PESA transfer/cash-conversion configuration, not all modern mobile-money products.',test('evaluated','SMS instruction and registered balance -> transfer between accounts -> local agent cash redemption -> usable remittance.','A handset-only account of adoption omits cash conversion and institutional acceptance.','If phones alone sufficed for cash redemption, withdrawals would not depend on agent cash or network functioning.','DIG-S08 describes cash/e-float operations and Tables14a–14b identify agent cash and network problems in actual withdrawal delays.','Supports operational complement requirements; does not determine their separate shares in aggregate diffusion.')),
claim(15,[5],'In Jack and Suri’s2008/2009 survey rounds,20% and16% of user households reported withdrawal delays; agent cash shortages and network outages were among reported causes.','scholarly-analysis','medium','mechanism-supported',[ref(8,'Tables14a–14b, printedpp.25–26','Reported encounter rates and categories of delay.')],'Most reported delays resolved within a day; expanding use and changing user composition complicate comparisons.','Not transaction-level failure probabilities; delays are retrospective reports.',test('evaluated','Agent cash shortage or network outage -> inability to redeem immediately -> withdrawal delay.','Personal documentation or deleted messages also generate delays; general dislike of technology does not predict the reported operational cause categories.','Cause-coded delays should include liquidity/network problems rather than only user preferences.','DIG-S08 Table14a reports both liquidity and network causes, with other cause categories retained.','Self-attribution and nonconstant user composition limit quantitative causal apportionment.','emerged during research')),
claim(16,[5],'Suri and Jack estimated about194,000 Kenyan households escaped extreme poverty through increased mobile-money access, using2008–2010 agent expansion to explain2014 outcomes; this is conditional quasi-experimental estimation, not a direct beneficiary count.','scholarly-analysis','medium','causal-identification',[ref(9,'pp.1288–1292; equations1–2; Table1; attrition discussion','Design, authors’ national extrapolation and limits.')],'Early agent placement could correlate with unobserved opportunity;35% non-Nairobi attrition and later exclusion of Nairobi limit inference. Authors report no definitive evidence for all channels.','Supplementary tests were described in main paper but not separately inspected or replicated; later2010–2014 rollout was intentionally not used as exogenous.',test('evaluated','Early agent access growth -> easier financial transactions/saving/risk sharing -> occupational/consumption changes by2014 -> lower estimated poverty.','Agents may enter places with unobserved growth prospects; those prospects could independently improve outcomes.','Pre-rollout consumption/risk sharing and characteristics should not predict later access growth; estimates should survive plausible attrition selection.','Read DIG-S09 main-text description of pretests, location fixed effects and attrition bounds, plus Table1 outcomes; supplementary tables and raw replication not acquired.','Reported falsification tests reduce some concerns but cannot eliminate unobserved trends or validate national extrapolation; data lineage overlaps DIG-S08.')),
claim(17,[5],'The2024 FinAccess report gives current mobile-money use of82.3% among Kenyan adults18+, across providers, and identifies lack of a phone or identity documentation among non-use barriers.','official-statistics','high','descriptive',[ref(10,'Methodologypp.3–5; Figure2.3p.12; usagep.26','Analysis age, current-use level and barrier narrative.')],'Some adults remain outside the system; bank services and mobile money can coexist.','Not M-PESA market share, registered-account counts or a fixed-window active-use measure.'),
claim(18,[6],'Ofcom’s2023 Core Survey of UK adults16+ reports gaming on VR devices4%, phones34%, consoles22%, tablets14%, laptops/netbooks10%, desktops8%; responses are non-exclusive and have no weekly/monthly threshold.','official-statistics','high','descriptive',[ref(15,'Table74 G1 pp.307–308; fieldwork header','Matched device question, levels and3,643 base.'),ref(16,'pp.7–8','2,121 face-to-face plus1,522 online quota interviews; adult weighting.')],'VR use was9% among16–24-year-olds; non-gaming and non-UK use are outside this measure.','Rounded survey estimates, not headset ownership/sales, monthly-active users or retention. Fieldwork27Sep–12Nov2023.'),
claim(19,[6],'A2022 Quest2 study found worse subjective ratings for prolonged VR desktop work than a matched physical setup among16 university-worker completers; two additional participants withdrew on the first VR day.','experiment','medium','causal-identification',[ref(12,'Sections3.1–3.4,3.6–3.7 and4','Counterbalanced study, apparatus, sample, subjective results and withdrawals.')],'Some discomfort improved with time; the experiment did not optimise the spatial advantages of VR or test other tasks/hardware.','Small occupational sample; subjective productivity is not objective output; treatment includes headset/interface/remote-work bundle.',test('evaluated','Prolonged use of tested headset/interface -> discomfort and interaction burden -> worse reported usability and productivity.','Novelty, the chosen display/input setup and differing actual work across weeks could drive the same ratings.','Within-person, counterbalanced physical comparison with matched inputs should reveal a condition effect; persistence across optimised systems would distinguish general wearing costs.','DIG-S12 provided a counterbalanced matched-environment study and reported adverse ratings plus withdrawals; no matched alternative-headset experiment located within this source set.','Experiment identifies this treatment bundle more credibly than any individual ergonomic mechanism; cannot extrapolate to all VR.')),
claim(20,[6],'Meta reported FY2023 Reality Labs revenue$1.896billion and operating loss$16.120billion for a segment including AR, mixed reality and VR hardware/software/content.','historical-primary','high','descriptive',[ref(13,'Note16, pp.124–125','Segment definition, allocation description and accounting table.')],'Large investment can finance development of future products as well as current consumption.','Not number of VR users, per-device loss or retention; company has commercial interests.'),
claim(21,[6],'The inspected Ofcom statistics establish minority UK VR gaming participation in2023 relative to matched devices; they do not establish a global installed base, fixed-window use or retention rate.','synthesis-inference','high','descriptive',[ref(11,'p.68 and footnote178','Summary points to2023 tracker but contains inconsistent comparison-year parenthesis.'),ref(15,'Table74 G1 pp.307–308','Underlying question/denominator resolves level but has no fixed recency/frequency threshold.'),ref(16,'pp.7–8','Population and method scope.')],'Other places, ages, tasks and VR configurations may have different adoption patterns.','No claim that4% means commercially trivial or that VR failed as a technology.'),
claim(22,[7],'Microsoft reported36.8million Lumia and126.8million other non-Lumia phone sales inFY2015 alongside$7.5billion phone-business impairments and strategic retrenchment;FY2014 sales covered only the post-acquisition period.','historical-primary','high','descriptive',[ref(14,'Shareholder letter; MD&A Phone Hardware; impairment discussion','Sales, charges, strategic scope and incomplete2014 comparison.')],'Substantial sales show deployment and users, so this is not a zero-adoption case.','Impairments reassess asset values; they do not identify current active users or the unique cause of strategic failure.'),
claim(23,[7],'Software/content coordination is a plausible contributor to the Microsoft phone episode, but its2015 stated unified-application strategy does not establish that app shortages caused the retrenchment.','synthesis-inference','low','hypothesis',[ref(14,'Create more personal computing; MD&A Phone Hardware; impairment discussion','Company’s intended ecosystem strategy and business outcome, not causal proof.')],'Distribution, timing, acquisition valuation, margins and execution also fit the outcome.','No independent app availability, carrier incentives or buyer switching data inspected.',test('underdetermined','Larger compatible app/user network -> developer/distributor participation -> buyer service availability -> sustainable phone demand.','Execution/valuation/distribution problems could cause the impairment even with adequate apps.','Compare local uptake and retention when app availability changes but price, hardware and distribution are held similar.','Read DIG-S14 strategy and financial result; found management emphasis on common apps but no discriminating consumer/developer panel.','Outcome and management explanation cannot isolate network effects or switching costs.')),
claim(24,[3,4,6],'Pocket internet, performance, ergonomics and cost cannot be causally ranked from these observations; the claim that most laptops cost less than most smartphones is unestablished by this source set.','synthesis-inference','medium','hypothesis',[ref(4,'Figure5.20','Reported importance, without component intervention or price distributions.'),ref(5,'Smartphone dependence and financial constraints','Constrained access is a rival to pure preference.'),ref(6,'Table6.2','Service-unit revenue is distinct from device purchase price.'),ref(15,'M6A;G1','Task perceptions and matched participation outcomes, not determinant coefficients.')],'Phones can be useful despite document difficulty; low data unit cost can coexist with higher spending;VR participation differs by task.','No dated sales-weighted laptop/smartphone price distributions or matched causal choice experiment inspected.',test('underdetermined','Portable connected device -> more moments of available service -> higher reported importance for certain tasks.','App/social coordination, constrained alternatives, status, habit and pricing can produce the same preference pattern.','Hold task, service availability, total cost and experience similar while varying portability/performance; independently measure prices and actual choices.','Sought matched official device-use measures: DIG-S04 and DIG-S15 found task-specific preferences/difficulty; DIG-S05 found financial dependence; no component-separating design or price-distribution dataset found in selected sources.','The findings fit multiple accounts; lack of price data establishes no ordering in either direction.'))
]
# Keep prose spacing legible in the compact literals above.
import re
for c in claims:
 for k in ['statement','counterevidence','inference_limits']:
  c[k]=re.sub(r'(?<=[A-Za-z%])(?=\d)', ' ', c[k])
write('claims.json',claims)

def episode(config,task,pop,interval,alts,measure,limits):
 return dict(technology_configuration=config,task=task,population=pop,interval=interval,contemporary_alternatives=alts,adoption_measure=measure,observation_limits=limits)
def actors(chooser,payer,op,non,refuse):
 return dict(chooser=chooser,payer=payer,operator_maintainer=op,affected_nonchooser=non,ability_to_refuse=refuse)
def labour(tasks,barriers,ownership,transition,distribution,limit):
 return dict(tasks=tasks,entry_barriers=barriers,bargaining_ownership=ownership,transition=transition,distribution=distribution,evidence_limit=limit)
