# Human-readable spacing in prose; preserve identifiers, URLs and hardware model tokens.
def clean_text(value,key=''):
 if isinstance(value,list): return [clean_text(x,key) for x in value]
 if isinstance(value,dict): return {k:clean_text(v,k) for k,v in value.items()}
 if not isinstance(value,str) or key=='id' or key.endswith('_id') or key in ['from','to'] or value.startswith('http'): return value
 protected={}
 def save(m):
  marker='QQPROTECTED'+chr(65+len(protected))+'QQ'
  protected[marker]=m.group(0)
  return marker
 value=re.sub(r'\bDIG-[A-Z]\d{2}\b|\bK830\b',save,value)
 value=re.sub(r'(?<=[A-Za-z])(?=\d)',' ',value)
 value=re.sub(r'(?<=\d)(?=[A-Za-z]{2,}\b)',' ',value)
 value=re.sub(r'(?<=%)(?=[A-Za-z0-9])',' ',value)
 value=re.sub(r'(?<=[A-Za-z])(?=[$₹])',' ',value)
 value=re.sub(r'(?<=[,;])(?=[A-Za-z0-9])',' ',value)
 prose_spacing={
  'MetaFY':'Meta FY', 'MicrosoftFY':'Microsoft FY', 'SectionII':'Section II',
  'inFY':'in FY', 'perGB':'per GB', 'allVRwork':'all VR work', 'allVR':'all VR',
  'reportedJun':'reported Jun', 'OtherVR':'Other VR', 'workplaceVR':'workplace VR',
  'thatVR':'that VR', 'salesFY':'sales FY', 'acquisitionFY':'acquisition FY',
  'ExistingPC':'Existing PC', 'PartialFY':'Partial FY', 'episodeFY':'episode FY',
  'laterUK':'later UK', 'andUS':'and US', 'outsideKenya':'outside Kenya',
  'callingVR':'calling VR', 'withinG':'within G', 'andS':'and S',
  'sameOfcom':'same Ofcom', 'MetaRLoperating':'Meta RL operating',
  'mixesAR':'mixes AR', 'printedpp':'printed pp',
 }
 for joined,separated in prose_spacing.items(): value=value.replace(joined,separated)
 for marker,original in protected.items(): value=value.replace(marker,original)
 return value
for fn,obj in [('sources.json',sources),('claims.json',claims),('cases.json',cases),('graph.json',dict(nodes=nodes,edges=edges)),('comparisons.json',comparisons)]: write(fn,clean_text(obj))
